(()=>{var BASE_URL=location.origin+"/";document.querySelector("head base").href=BASE_URL;document.getElementById("date").innerHTML=`&copy; ${new Date().getFullYear()} - Code free for fun`;var secondsElement=document.querySelector(".seconds"),minutesElement=document.querySelector(".minutes"),hoursElement=document.querySelector(".hours"),timeElement=document.querySelector(".time"),setRotation=(element,rotation)=>element.style.transform=`rotate(${rotation}deg)`,updateWatch=()=>{let now=new Date,seconds=now.getSeconds(),minutes=now.getMinutes(),hours=now.getHours(),secondsRotation=seconds*6,minutesRotation=minutes*6+seconds*.1,hoursRotation=hours*30+minutes*.5;setRotation(secondsElement,secondsRotation),setRotation(minutesElement,minutesRotation),setRotation(hoursElement,hoursRotation);let formattedHours=String(hours).padStart(2,"0"),formattedMinutes=String(minutes).padStart(2,"0");timeElement.textContent=`${formattedHours}:${formattedMinutes}`};setInterval(updateWatch,1e3);updateWatch();})();
